window.AUTH=window.AUTH||{};window.AUTH["17-71"]={"d":"17-71","id":"2018/17-71","n":"Weyerhaeuser Company v. United States Fish and Wildlife Service","briefs":[{"k":"petitioner","label":"Brief of petitioner Weyerhaeuser Company","date":"2018-04-23","url":"https://www.supremecourt.gov/DocketPDF/17/17-71/44376/20180423155723573_17-71ts.pdf","side":"pet","n":53},{"k":"respondent","label":"Brief of respondents Markle Interests, LLC, et al. in support of petitioner","date":"2018-04-23","url":"https://www.supremecourt.gov/DocketPDF/17/17-71/44277/20180423113126083_Respondent%20Markle%20Brief%20on%20the%20Merits.pdf","side":"res","n":49},{"k":"respondent","label":"Brief of respondents United States Fish and Wildlife Service, et al.","date":"2018-06-29","url":"https://www.supremecourt.gov/DocketPDF/17/17-71/51924/20180629185347041_17-71bsUnitedStates.pdf","side":"res","n":108},{"k":"reply","label":"Reply of petitioner Weyerhaeuser Company","date":"2018-08-13","url":"https://www.supremecourt.gov/DocketPDF/17/17-71/59271/20180813145223105_17-71%20rb.pdf","side":"pet","n":43}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-71_omjp.pdf","tr":true,"items":[{"t":"case","label":"Ariz. Cattle Growers’ Ass’n v. Salazar","cite":"606 F.3d 1160","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/606/1160/","by":{"0":"36","1":"30"}},{"t":"case","label":"Ayestas v. Davis","cite":"138 S. Ct. 1080","y":2018,"id":"2017/16-6795","sc":1,"sum":"The Court decided that the district court's denial of petitioner's request for \"reasonably necessary\" investigative and related services under 18 U.S.C. § 3599(f) to prove that he was entitled to federal habeas relief was a judicial decision subject to appellate review under the standard jurisdictional provisions; and that the U.S. Court of Appeals for the 5th Circuit applied the wrong legal standard in affirming the district court's denial of petitioner's § 3599(f) request.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Babbitt v. Sweet Home Chapter of Communities for a Great Oregon","cite":"515 U.S. 687","y":1995,"id":"1994/94-859","sc":1,"sum":"The Supreme Court held that habitat modification is a legitimate application of the word \"harm.\" First, the Court found that the Court of Appeals was incorrect in assuming that the words in the definition of \"take\" only apply to actions involving direct contact with endangered animals.","sumSrc":"Oyez","by":{"0":"passim","1":"32","2":"5, 30, 31, 32, 41, 51"}},{"t":"case","label":"Bayer CropScience AG v. Dow AgroSciences LLC","cite":"728 F.3d 1324","y":2013,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/728/1324/","by":{"0":"26"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"op":2,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"0":"passim","1":"23, 49-50","2":"45, 49, 50","3":"passim"}},{"t":"case","label":"Beno v. Shalala","cite":"30 F.3d 1057","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/30/1057/","by":{"0":"49"}},{"t":"case","label":"Buffalo River Watershed Alliance v. Dep’t of Agriculture","cite":"2014 WL 6837005","y":2014,"court":"E.D. Ark. Dec. 2","by":{"0":"6"}},{"t":"case","label":"Burlington Truck Lines, Inc. v. United States","cite":"371 U.S. 156","y":1962,"id":"1962/27","sc":1,"sum":"The judgment is reversed and the case is remanded to the District Court with instructions to set aside the Commission's order and remand the case to the Commission for further proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"52"}},{"t":"case","label":"Calf Island Cmty. Trust, Inc. v. Young Mens Christian Ass’n of Greenwich","cite":"392 F. Supp. 2d 241","y":2005,"court":"D. Conn.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/392/241/","by":{"0":"42"}},{"t":"case","label":"Cape Hatteras Access Pres. All. v. U.S. Dep’t of Interior","cite":"344 F. Supp. 2d 108","y":2004,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/344/108/","by":{"0":"27, 36","1":"passim"}},{"t":"case","label":"Chappell v. Wallace","cite":"462 U.S. 296","y":1983,"id":"1982/82-167","sc":1,"sum":"Enlisted military personnel may not maintain a suit to recover damages from a superior officer for alleged constitutional violations. The special status of the military has required, the Constitution has contemplated, Congress has created, and this Court has long recognized two systems of justice: one for civilians and one for military personnel. The need for unhesitating and decisive action by military officers and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48","3":"16"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. NRDC","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"29, 36","1":"passim","2":"31","3":"11, 14"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"32","3":"12"}},{"t":"case","label":"Defs. of Wildlife v. Bureau of Ocean Energy Management","cite":"871 F. Supp. 2d 1312","y":2012,"court":"S.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/871/1312/","by":{"0":"6"}},{"t":"case","label":"Dickson v. Sec’y of Def.","cite":"68 F.3d 1396","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/68/1396/","by":{"0":"48","1":"46-47"}},{"t":"case","label":"Digital Realty Trust, Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"136 S. Ct. 2117","y":2016,"id":"2015/15-415","sc":1,"sum":"The Court held that, because the Department of Labor did not give adequate reasons for altering its position on whether service advisors are exempt from overtime compensation under the Fair Labor Standards Act (FLSA), the case should be remanded for reinterpretation that does not give controlling weight to the Department’s 2011 position.","sumSrc":"Oyez","by":{"0":"53","1":"46-47"}},{"t":"case","label":"Esquivel-Quintana v. Sessions","cite":"137 S. Ct. 1562","y":2017,"id":"2016/16-54","sc":1,"sum":"The Court determined that the crime of “unlawful sexual intercourse with a minor” as defined by California law cannot be categorically considered the aggravated felony of “sexual abuse of a minor” for the purpose of mandatory removal under the Immigration and Nationality Act (INA).","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Florida Key Deer v. Paulison","cite":"522 F.3d 1133","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/522/1133/","by":{"0":"6"}},{"t":"case","label":"Forest Grove Sch. Dist. v. T.A.","cite":"557 U.S. 230","y":2009,"id":"2008/08-305","sc":1,"sum":"The Court found that the Individuals with Disabilities Education Act (IDEA) can authorize a public school to reimburse a student for private school tuition sought because the student never received special education services at the public school.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Forest Guardians v. U.S. FWS","cite":"611 F.3d 692","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/611/692/","by":{"0":"42"}},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"sum":"Evaluating the Secretary's chosen procedure under Article I Section 2 of the Constitution, however, Justice O'Connor ruled that the decision to include overseas personnel of the Department of Defense was a reasonable interpretation of the Constitution's intent. \"The Secretary's judgment does not hamper the underlying constitutional goal of equal representation, but, assuming that employees temporarily stationed abroad have indeed retained their ties to their home states, actually promotes equality,\" wrote Justice O'Connor.","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Heckler v. Chaney","cite":"470 U.S. 821","y":1985,"id":"1984/83-1878","sc":1,"op":1,"sum":"They are presumptively unreviewable. Refusals of administrative agencies to exercise enforcement authority involve a complicated balancing of factors, including agency allocation of scarce resources, which are not suitable for judicial review. Thus, they are presumptively \"committed to agency discretion by law\" under Section 701(a)(2).","sumSrc":"Oyez","by":{"0":"50, 51, 56","1":"passim","2":"46, 49"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"26","3":"10"}},{"t":"case","label":"Home Builders Ass’n of N. Cal. v. U.S. Fish & Wildlife Service","cite":"616 F.3d 983","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/616/983/","by":{"0":"27, 36","1":"22, 30","2":"26, 40"}},{"t":"case","label":"Koontz v. St. Johns River Water Management Dist.","cite":"570 U.S. 595","y":2013,"id":"2012/11-1447","sc":1,"sum":"The Court held that the government may not conditionally approve land-use permits unless the conditions are connected and approximately proportionate to the effects of the proposed land use.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"135 S. Ct. 1645","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1645/","sc":1,"op":1,"by":{"0":"46, 48, 49","2":"48, 49","3":"17"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n of U.S., Inc. v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","3":"18"}},{"t":"case","label":"Nat’l Ass’n of Home Builders v. Babbitt","cite":"130 F.3d 1041","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/130/1041/","by":{"0":"34","2":"44"}},{"t":"case","label":"Nat’l Ass’n of Home Builders v. Defs. of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"op":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"0":"5, 29","2":"6"}},{"t":"case","label":"Nat’l Fed’n of Indep. Bus. v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Octane Fitness, LLC v. ICON Health & Fitness, Inc.","cite":"134 S. Ct. 1749","y":2014,"id":"2013/12-1184","sc":1,"sum":"A case in which the Court defined \"exceptional\" cases as ones that simply stand out from others due to a frivolous nature related to its legal claims.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"sum":"The plurality rejected the argument that only actually-navigable waters can be regulated by the Clean Water Act, but also held that the word \"navigable\" in the Act cannot be divested of all meaning. The plurality held that the definitional term \"waters of the United States\" can only refer to \"relatively permanent, standing or flowing bodies of water,\" not \"occasional,\" \"intermittent,\" or \"ephemeral\" flows.","sumSrc":"Oyez","by":{"0":"32, 33","2":"13"}},{"t":"case","label":"Solid Waste Agency of N. Cook Cty. v. U.S. Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"sum":"The Court held that the provision of the CWA, which requires those discharging fill material into navigable waters to obtain a permit from the Corps, does not extend to isolated, abandoned sand and gravel pits with seasonal ponds, which provide migratory bird habitats.","sumSrc":"Oyez","by":{"0":"26, 32, 34, 35","1":"22, 36-38","2":"13, 26, 29, 43","3":"4, 12"}},{"t":"case","label":"Sweet Home Chapter of Communities for a Great Oregon v. Babbitt","cite":"1 F.3d 1","y":1993,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/1/1/","by":{"0":"41"}},{"t":"case","label":"Taniguchi v. Kan Pac. Saipan, Ltd.","cite":"566 U.S. 560","y":2012,"id":"2011/10-1472","sc":1,"sum":"The Court held that the winner of a federal-court lawsuit cannot be reimbursed by the losing party for any document translation costs under 28 U.S.C. § 1920(6).","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Tennessee Valley Auth. v. Hill","cite":"437 U.S. 153","y":1978,"id":"1977/76-1701","sc":1,"sum":"The Supreme Court held that Congress’ continued appropriation of funds did not imply that the Dam project was exempt from the ESA. The operation of the Tellico Dam would wipe out the Snail Darter's habitat, so an injunction was the proper remedy.","sumSrc":"Oyez","by":{"0":"passim","1":"32-33","2":"31","3":"5, 7, 10"}},{"t":"case","label":"United States v. Garcia","cite":"857 F.3d 708","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/857/708/","by":{"0":"26"}},{"t":"case","label":"Util. Air Regulatory Grp. v. EPA","cite":"134 S. Ct. 2427","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./134/2427/","sc":1,"by":{"0":"31"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"stext":{"head":"§1254. Courts of appeals; certiorari; certified questions","paras":[[0,"Cases in the courts of appeals may be reviewed by the Supreme Court by the following methods:"],[1,"(1) By writ of certiorari granted upon the petition of any party to any civil or criminal case, before or after rendition of judgment or decree;"],[1,"(2) By certification at any time by a court of appeals of any question of law in any civil or criminal case as to which instructions are desired, and upon such certification the Supreme Court may give binding instructions or require the entire record to be sent up for decision of the entire matter in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1254?type=usc&year=mostrecent&link-type=html"},"head":"§1254. Courts of appeals; certiorari; certified questions","tname":"Judiciary and Judicial Procedure","by":{"0":"1","1":"1"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)(1)","(a)(2)"],"stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"0":"48, 51","1":"3, 41-42","2":"15, 13"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","stext":{"head":"§1251. Congressional declaration of goals and policy","paras":[[0,"(a) Restoration and maintenance of chemical, physical and biological integrity of Nation's waters; national goals for achievement of objective"],[0,"The objective of this chapter is to restore and maintain the chemical, physical, and biological integrity of the Nation's waters. In order to achieve this objective it is hereby declared that, consistent with the provisions of this chapter—"],[1,"(1) it is the national goal that the discharge of pollutants into the navigable waters be eliminated by 1985;"],[1,"(2) it is the national goal that wherever attainable, an interim goal of water quality which provides for the protection and propagation of fish, shellfish, and wildlife and provides for recreation in and on the water be achieved by July 1, 1983;"],[1,"(3) it is the national policy that the discharge of toxic pollutants in toxic amounts be prohibited;"],[1,"(4) it is the national policy that Federal financial assistance be provided to construct publicly owned waste treatment works;"],[1,"(5) it is the national policy that areawide waste treatment management planning processes be developed and implemented to assure adequate control of sources of pollutants in each State;"],[1,"(6) it is the national policy that a major research and demonstration effort be made to develop technology necessary to eliminate the discharge of pollutants into the navigable waters, waters of the contiguous zone, and the oceans; and"],[1,"(7) it is the national policy that programs for the control of nonpoint sources of pollution be developed and implemented in an expeditious manner so as to enable the goals of this chapter to be met through the control of both point and nonpoint sources of pollution."],[0,"(b) Congressional recognition, preservation, and protection of primary responsibilities and rights of States"],[0,"It is the policy of the Congress to recognize, preserve, and protect the primary responsibilities and rights of States to prevent, reduce, and eliminate pollution, to plan the development and use (including restoration, preservation, and enhancement) of land and water resources, and to consult with the Administrator in the exercise of his authority under this chapter. It is the policy of Congress that the States manage the construction grant program under this chapter and implement the permit programs under sections 1342 and 1344 of this title. It is further the policy of the Congress to support and aid research relating to the prevention, reduction, and elimination of pollution and to provide Federal technical services and financial aid to State and interstate agencies and municipalities in connection with the prevention, reduction, and elimination of pollution."],[0,"(c) Congressional policy toward Presidential activities with foreign countries"],[0,"It is further the policy of Congress that the President, acting through the Secretary of State and such national and international organizations as he determines appropriate, shall take such action as may be necessary to insure that to the fullest extent possible all foreign countries shall take meaningful action for the prevention, reduction, and elimination of pollution in their waters and in international waters and for the achievement of goals regarding the elimination of discharge of pollutants and the improvement of water quality to at least the same extent as the United States does under its laws."],[0,"(d) Administrator of Environmental Protection Agency to administer chapter"],[0,"Except as otherwise expressly provided in this chapter, the Administrator of the Environmental Protection Agency (hereinafter in this chapter called \"Administrator\") shall administer this chapter."],[0,"(e) Public participation in development, revision, and enforcement of any regulation, etc."],[0,"Public participation in the development, revision, and enforcement of any regulation, standard, effluent limitation, plan, or program established by the Administrator or any State under this chapter shall be provided for, encouraged, and assisted by the Administrator and the States. The Administrator, in cooperation with the States, shall develop and publish regulations specifying minimum guidelines for public participation in such processes."],[0,"(f) Procedures utilized for implementing chapter"],[0,"It is the national policy that to the maximum extent possible the procedures utilized for implementing this chapter shall encourage the drastic minimization of paperwork and interagency decision procedures, and the best use of available manpower and funds, so as to prevent needless duplication and unnecessary delays at all levels of government."],[0,"(g) Authority of States over water"],[0,"It is the policy of Congress that the authority of each State to allocate quantities of water within its jurisdiction shall not be superseded, abrogated or otherwise impaired by this chapter. It is the further policy of Congress that nothing in this chapter shall be construed to supersede or abrogate rights to quantities of water which have been established by any State. Federal agencies shall co-operate with State and local agencies to develop comprehensive solutions to prevent, reduce and eliminate pollution in concert with programs for managing water resources."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1251?type=usc&year=mostrecent&link-type=html"},"head":"§1251. Congressional declaration of goals and policy","tname":"Navigation and Navigable Waters","by":{"0":"6","2":"13"}},{"t":"usc","label":"16 U.S.C. § 1531","url":"https://www.law.cornell.edu/uscode/text/16/1531","subs":["(b)","(c)(1)"],"stext":{"head":"§1531. Congressional findings and declaration of purposes and policy","paras":[[0,"(a) Findings"],[0,"The Congress finds and declares that—"],[1,"(1) various species of fish, wildlife, and plants in the United States have been rendered extinct as a consequence of economic growth and development untempered by adequate concern and conservation;"],[1,"(2) other species of fish, wildlife, and plants have been so depleted in numbers that they are in danger of or threatened with extinction;"],[1,"(3) these species of fish, wildlife, and plants are of esthetic, ecological, educational, historical, recreational, and scientific value to the Nation and its people;"],[1,"(4) the United States has pledged itself as a sovereign state in the international community to conserve to the extent practicable the various species of fish or wildlife and plants facing extinction, pursuant to—"],[2,"(A) migratory bird treaties with Canada and Mexico;"],[2,"(B) the Migratory and Endangered Bird Treaty with Japan;"],[2,"(C) the Convention on Nature Protection and Wildlife Preservation in the Western Hemisphere;"],[2,"(D) the International Convention for the Northwest Atlantic Fisheries;"],[2,"(E) the International Convention for the High Seas Fisheries of the North Pacific Ocean;"],[2,"(F) the Convention on International Trade in Endangered Species of Wild Fauna and Flora; and"],[2,"(G) other international agreements; and"],[1,"(5) encouraging the States and other interested parties, through Federal financial assistance and a system of incentives, to develop and maintain conservation programs which meet national and international standards is a key to meeting the Nation's international commitments and to better safeguarding, for the benefit of all citizens, the Nation's heritage in fish, wildlife, and plants."],[0,"(b) Purposes"],[0,"The purposes of this chapter are to provide a means whereby the ecosystems upon which endangered species and threatened species depend may be conserved, to provide a program for the conservation of such endangered species and threatened species, and to take such steps as may be appropriate to achieve the purposes of the treaties and conventions set forth in subsection (a) of this section."],[0,"(c) Policy"],[0,"(1) It is further declared to be the policy of Congress that all Federal departments and agencies shall seek to conserve endangered species and threatened species and shall utilize their authorities in furtherance of the purposes of this chapter."],[0,"(2) It is further declared to be the policy of Congress that Federal agencies shall cooperate with State and local agencies to resolve water resource issues in concert with conservation of endangered species."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1531?type=usc&year=mostrecent&link-type=html"},"head":"§1531. Congressional findings and declaration of purposes and policy","tname":"Conservation","by":{"0":"1","2":"2, 41, 41","3":"10"}},{"t":"reg","label":"50 C.F.R. § 17.3","url":"https://www.ecfr.gov/current/title-50/section-17.3","by":{"0":"5, 39"}},{"t":"reg","label":"43 Fed. Reg. 870","url":"https://www.govinfo.gov/link/fr/43/870","by":{"0":"8, 31","2":"39","3":"11"}},{"t":"reg","label":"62 Fed. Reg. 39129","url":"https://www.govinfo.gov/link/fr/62/39129","by":{"0":"42"}},{"t":"reg","label":"64 Fed. Reg. 31871","url":"https://www.govinfo.gov/link/fr/64/31871","by":{"0":"43"}},{"t":"reg","label":"66 Fed. Reg. 62993","url":"https://www.govinfo.gov/link/fr/66/62993","by":{"0":"passim","1":"7","2":"6, 7, 8, 9, 10, 34","3":"1"}},{"t":"reg","label":"68 Fed. Reg. 46684","url":"https://www.govinfo.gov/link/fr/68/46684","by":{"0":"43"}},{"t":"reg","label":"69 Fed. Reg. 59996","url":"https://www.govinfo.gov/link/fr/69/59996","by":{"0":"43"}},{"t":"reg","label":"77 Fed. Reg. 35118","url":"https://www.govinfo.gov/link/fr/77/35118","by":{"0":"passim","1":"passim","2":"10","3":"passim"}},{"t":"reg","label":"81 Fed. Reg. 7414","url":"https://www.govinfo.gov/link/fr/81/7414","by":{"0":"11, 36"}},{"t":"law","label":"Pub. L. No. 93-205","url":"https://www.govinfo.gov/link/statute/87/884","by":{"0":"30"}},{"t":"case","label":"All. for Wild Rockies v. Lyder","cite":"728 F. Supp. 2d 1126","y":2010,"court":"D. Mont.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/728/1126/","by":{"1":"30"}},{"t":"case","label":"Am. Forest Res. Council v. Ashe","cite":"946 F. Supp. 2d 1","y":2013,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/946/1/","by":{"1":"30"}},{"t":"case","label":"Columbia Falls Aluminum Co. v. Environmental Prot. Agency","cite":"139 F.3d 914","y":1998,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/139/914/","by":{"1":"23, 49"}},{"t":"case","label":"Ctr. for Biological Diversity v. Kelly","cite":"93 F. Supp. 3d 1193","y":2015,"court":"D. Idaho","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/93/1193/","by":{"1":"30"}},{"t":"case","label":"Federal Communications Comm’n v. Fox Television Stations, Inc.","cite":"556 U.S. 502","y":2009,"id":"2008/07-582","sc":1,"sum":"The Court held that the FCC's imposition of liability on Fox Television Stations for fleeting expletives was not \"arbitrary and capricious\" under the Administrative Procedure Act, even though the FCC previously accepted similar expletives.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Hughes Aircraft Co. v. Jacobson","cite":"525 U.S. 432","y":1999,"id":"1998/97-1287","sc":1,"sum":"The Court held Hughes did not violate the ERISA by establishing an early retirement program and creating a noncontributory benefit structure for new participants. Justice Thomas, writing for the Court, said the plan amendments \"did not affect the rights of pre-existing plan participants and Hughes did not use the surplus for its own benefit.\".","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Lamie v. U.S. Tr.","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"1":"25, 28"}},{"t":"case","label":"Markle Interests, L.L.C. v. United States Fish and Wildlife Service","cite":"40 F. Supp. 3d 744","y":2014,"court":"E.D. La.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/40/744/","op":1,"by":{"1":"1"}},{"t":"case","label":"Markle Interests, L.L.C. v. United States Fish and Wildlife Service","cite":"827 F.3d 452","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/827/452/","op":3,"by":{"1":"1"}},{"t":"case","label":"Markle Interests, L.L.C. v. United States Fish and Wildlife Service","cite":"848 F.3d 635","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/848/635/","op":1,"by":{"1":"1, 19-20"}},{"t":"case","label":"Markle Interests, LLC v. U.S. Fish & Wildlife Serv.","cite":"2017 WL 606513","y":2017,"court":"5th Cir. Feb. 13","by":{"1":"44"}},{"t":"case","label":"MCI Telecomms. Corp. v. AT&T Co.","cite":"512 U.S. 218","y":1994,"id":"1993/93-356","sc":1,"sum":"The Commission's permissive detariffing policy is not a valid exercise of its §203(b)(2) authority to \"modify any requirement.\" Because virtually every dictionary in use now and at the time the statute was enacted defines \"to modify\" as meaning to change moderately or in minor fashion, the word \"modify\" must be seen to have a connotation of increment or limitation. That § 203(b)(2) does not contemplate basic or …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Michigan v. Environmental Prot. Agency","cite":"135 S. Ct. 2699","y":2015,"id":"2014/14-46","sc":1,"sum":"The Court determined that the Environmental Protection Agency (EPA) unreasonably interpreted the Clean Air Act by not considering costs to power plants in deciding that regulation was “appropriate and necessary.”","sumSrc":"Oyez","by":{"1":"39, 48"}},{"t":"case","label":"Nat’l Fed’n of Indep. Bus. v. Sebelius","cite":"132 S. Ct. 2566","y":2012,"url":"https://www.courtlistener.com/c/S.%20Ct./132/2566/","sc":1,"by":{"1":"37"}},{"t":"case","label":"National Cable & Telecomms. Ass’n v. Brand X Internet Servs.","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"sum":"The Court held that the FCC lawfully construed the Communications Act to not define cable broadband providers as \"telecommunications services.\" The Court held that the Ninth Circuit should have followed the Supreme Court's 1984 decision in Chevron v. Natural Resources Defense Council.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"NISH v. Rumsfeld","cite":"348 F.3d 1263","y":2003,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/348/1263/","by":{"1":"24-25"}},{"t":"case","label":"Park ‘N Fly, Inc. v. Dollar Park and Fly, Inc.","cite":"469 U.S. 189","y":1985,"id":"1984/83-1132","sc":1,"sum":"The holder of a registered mark may rely on incontestability to enjoin infringement, and an infringement action may not be defended on the grounds that the mark is merely descriptive.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Pittston Coal Grp. v. Sebben","cite":"488 U.S. 105","y":1988,"id":"1988/87-821","sc":1,"sum":"The Black Lung Benefits Reform Act of 1977 (BLBRA), in 30 U. S. C. § 902(f)(2), provided that, pending the issuance of permanent regulations by the Secretary of Labor, cases filed or pending, as well as certain claims required to be reopened or readjudicated, were to be assessed under \"[c]riteria... not... more restrictive than the criteria applicable to a claim filed on June 30, 1973.\" As of that date, under …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"United States v. Am. Trucking Ass’ns","cite":"310 U.S. 534","y":1940,"id":"scdb/1939-042","sc":1,"sum":"1. The power of the Interstate Commerce Commission under the Motor Carrier Act, 1935, § 204 (a), to establish reasonable requirements with respect tolthe qualifications and maximum hou'rs of service of employees of motor carriers, is confined to those employees whose duties affect safety of operation. Pp. 546, 553.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"United States v. Lopez","cite":"514 U.S. 549","y":1995,"id":"1994/93-1260","sc":1,"sum":"The Court found the 1990 Gun-Free School Zones Act unconstitutional for overstepping the congressional boundaries of the Commerce Clause.","sumSrc":"Oyez","by":{"1":"36-37","2":"44"}},{"t":"case","label":"United States v. Morrison","cite":"529 U.S. 598","y":2000,"id":"1999/99-5","sc":1,"sum":"The Court found that sections of the Violence Against Women Act were unconstitutional under the Commerce Clause.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"ar":1,"sum":"Section 102(c) of the National Security Act of 1947 (NSA) authorizes the Director of the Central Intelligence Agency (CIA), \"in his discretion,\" to terminate the employment of any CIA employee \"whenever he shall deem such termination necessary or advisable in the interests of the United States.\" After respondent, a covert electronics technician in the CIA's employ, voluntarily informed the agency that he was a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"passim","2":"47, 49","3":"17"}},{"t":"const","label":"Amendment X","clauses":[["tenth-amendment","Tenth Amendment"]],"text":"The powers not delegated to the United States by the Constitution, nor prohibited by it to the States, are reserved to the States respectively, or to the people.","by":{"1":"1"}},{"t":"const","label":"Article I, Section 8, Clause 3","clauses":[["commerce","Commerce Clause"]],"text":"To regulate Commerce with foreign Nations, and among the several States, and with the Indian Tribes;","by":{"1":"1","2":"15, 44"}},{"t":"usc","label":"16 U.S.C. § 1532","url":"https://www.law.cornell.edu/uscode/text/16/1532","subs":["(5)","(3)","(5)(A)(i)","(5)(A)(ii)","(5)(C)","(6)","(15)","(19)","(20)"],"stext":{"head":"§1532. Definitions","paras":[[0,"For the purposes of this chapter—"],[1,"(1) The term \"alternative courses of action\" means all alternatives and thus is not limited to original project objectives and agency jurisdiction."],[1,"(2) The term \"commercial activity\" means all activities of industry and trade, including, but not limited to, the buying or selling of commodities and activities conducted for the purpose of facilitating such buying and selling: Provided, however, That it does not include exhibition of commodities by museums or similar cultural or historical organizations."],[1,"(3) The terms \"conserve\", \"conserving\", and \"conservation\" mean to use and the use of all methods and procedures which are necessary to bring any endangered species or threatened species to the point at which the measures provided pursuant to this chapter are no longer necessary. Such methods and procedures include, but are not limited to, all activities associated with scientific resources management such as research, census, law enforcement, habitat acquisition and maintenance, propagation, live trapping, and transplantation, and, in the extraordinary case where population pressures within a given ecosystem cannot be otherwise relieved, may include regulated taking."],[1,"(4) The term \"Convention\" means the Convention on International Trade in Endangered Species of Wild Fauna and Flora, signed on March 3, 1973, and the appendices thereto."],[1,"(5)(A) The term \"critical habitat\" for a threatened or endangered species means—"],[2,"(i) the specific areas within the geographical area occupied by the species, at the time it is listed in accordance with the provisions of section 1533 of this title, on which are found those physical or biological features (I) essential to the conservation of the species and (II) which may require special management considerations or protection; and"],[2,"(ii) specific areas outside the geographical area occupied by the species at the time it is listed in accordance with the provisions of section 1533 of this title, upon a determination by the Secretary that such areas are essential for the conservation of the species."],[1,"(B) Critical habitat may be established for those species now listed as threatened or endangered species for which no critical habitat has heretofore been established as set forth in subparagraph (A) of this paragraph."],[1,"(C) Except in those circumstances determined by the Secretary, critical habitat shall not include the entire geographical area which can be occupied by the threatened or endangered species."],[1,"(6) The term \"endangered species\" means any species which is in danger of extinction throughout all or a significant portion of its range other than a species of the Class Insecta determined by the Secretary to constitute a pest whose protection under the provisions of this chapter would present an overwhelming and overriding risk to man."],[1,"(7) The term \"Federal agency\" means any department, agency, or instrumentality of the United States."],[1,"(8) The term \"fish or wildlife\" means any member of the animal kingdom, including without limitation any mammal, fish, bird (including any migratory, nonmigratory, or endangered bird for which protection is also afforded by treaty or other international agreement), amphibian, reptile, mollusk, crustacean, arthropod or other invertebrate, and includes any part, product, egg, or offspring thereof, or the dead body or parts thereof."],[1,"(9) The term \"foreign commerce\" includes, among other things, any transaction—"],[2,"(A) between persons within one foreign country;"],[2,"(B) between persons in two or more foreign countries;"],[2,"(C) between a person within the United States and a person in a foreign country; or"],[2,"(D) between persons within the United States, where the fish and wildlife in question are moving in any country or countries outside the United States."],[1,"(10) The term \"import\" means to land on, bring into, or introduce into, or attempt to land on, bring into, or introduce into, any place subject to the jurisdiction of the United States, whether or not such landing, bringing, or introduction constitutes an importation within the meaning of the customs laws of the United States."],[1,"(11) Repealed. Pub. L. 97–304, §4(b), Oct. 13, 1982, 96 Stat. 1420."],[1,"(12) The term \"permit or license applicant\" means, when used with respect to an action of a Federal agency for which exemption is sought under section 1536 of this title, any person whose application to such agency for a permit or license has been denied primarily because of the application of section 1536(a) of this title to such agency action."],[1,"(13) The term \"person\" means an individual, corporation, partnership, trust, association, or any other private entity; or any officer, employee, agent, department, or instrumentality of the Federal Government, of any State, municipality, or political subdivision of a State, or of any foreign government; any State, municipality, or political subdivision of a State; or any other entity subject to the jurisdiction of the United States."],[1,"(14) The term \"plant\" means any member of the plant kingdom, including seeds, roots and other parts thereof."],[1,"(15) The term \"Secretary\" means, except as otherwise herein provided, the Secretary of the Interior or the Secretary of Commerce as program responsibilities are vested pursuant to the provisions of Reorganization Plan Numbered 4 of 1970; except that with respect to the enforcement of the provisions of this chapter and the Convention which pertain to the importation or exportation of terrestrial plants, the term also means the Secretary of Agriculture."],[1,"(16) The term \"species\" includes any subspecies of fish or wildlife or plants, and any distinct population segment of any species of vertebrate fish or wildlife which interbreeds when mature."],[1,"(17) The term \"State\" means any of the several States, the District of Columbia, the Commonwealth of Puerto Rico, American Samoa, the Virgin Islands, Guam, and the Trust Territory of the Pacific Islands."],[1,"(18) The term \"State agency\" means any State agency, department, board, commission, or other governmental entity which is responsible for the management and conservation of fish, plant, or wildlife resources within a State."],[1,"(19) The term \"take\" means to harass, harm, pursue, hunt, shoot, wound, kill, trap, capture, or collect, or to attempt to engage in any such conduct."],[1,"(20) The term \"threatened species\" means any species which is likely to become an endangered species within the foreseeable future throughout all or a significant portion of its range."],[1,"(21) The term \"United States\", when used in a geographical context, includes all States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1532?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1532. Definitions","tname":"Conservation","by":{"1":"8","2":"24, 24, 24, 24, 24, 24, 2, 2, 2, 2"}},{"t":"reg","label":"50 C.F.R. § 402.01","url":"https://www.ecfr.gov/current/title-50/section-402.01","subs":["(a)"],"by":{"1":"27"}},{"t":"reg","label":"75 Fed. Reg. 31387","url":"https://www.govinfo.gov/link/fr/75/31387","by":{"1":"8","2":"8, 9, 10"}},{"t":"reg","label":"75 Fed. Reg. 31389","url":"https://www.govinfo.gov/link/fr/75/31389","by":{"1":"7-8"}},{"t":"reg","label":"75 Fed. Reg. 39396","url":"https://www.govinfo.gov/link/fr/75/39396","by":{"1":"14"}},{"t":"reg","label":"76 Fed. Reg. 59774","url":"https://www.govinfo.gov/link/fr/76/59774","by":{"1":"9","2":"36","3":"2"}},{"t":"reg","label":"77 Fed. Reg. 35123","url":"https://www.govinfo.gov/link/fr/77/35123","by":{"1":"6, 12, 29"}},{"t":"reg","label":"77 Fed. Reg. 35124","url":"https://www.govinfo.gov/link/fr/77/35124","by":{"1":"11, 29"}},{"t":"case","label":"Alabama-Tombigbee Rivers Coal. v. Kempthorne","cite":"477 F.3d 1250","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/477/1250/","by":{"2":"44"}},{"t":"case","label":"Baldwin v. Fish & Game Comm’n","cite":"436 U.S. 371","y":1978,"id":"1977/76-1150","sc":1,"sum":"Justice Blackmun found that the Privileges and Immunities Clause only applied to activities which bear \"on the vitality of the Nation as a single entity.\" Since elk hunting is a recreational activity and not fundamental to the survival of nonresidents of Montana, Blackmun argued that it did not fall within the scope of the protections guaranteed by the Constitution. \"Equality in access to Montana elk is not basic to the maintenance or well-being of the Union,\" he concluded.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Baltimore Gas & Elec. Co. v. National Res. Def. Council, Inc.","cite":"462 U.S. 87","y":1983,"id":"1982/82-524","sc":1,"sum":"The NRC complied with NEPA, and its decision is not arbitrary or capricious within the meaning of § 10(e) of the Administrative Procedure Act (APA).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Bear Valley Mut. Water Co. v. Jewell","cite":"790 F.3d 977","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/790/977/","sum":"Upholding designation of sub-unit of critical habitat for Santa Ana sucker that provides coarse sediment for spawning elsewhere in unit.","sumSrc":"brief:2","by":{"2":"27, 48, 51"}},{"t":"case","label":"Building Indus. Ass’n of the Bay Area v. United States Dep’t of Commerce","cite":"792 F.3d 1027","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/792/1027/","by":{"2":"48, 49"}},{"t":"case","label":"Center for Biological Diversity v. United States Fish & Wildlife Serv.","cite":"2011 WL 73494","y":2011,"court":"C.D. Cal. Jan. 8","by":{"2":"27"}},{"t":"case","label":"Center for Native Ecosystems v. Cables","cite":"509 F.3d 1310","y":2007,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/509/1310/","by":{"2":"4"}},{"t":"case","label":"Central Va. Cmty. Coll. v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"sum":"The Court ruled that states cannot invoke sovereign immunity as a defense in bankruptcy proceedings. Rather than ruling on the power of Congress under the Bankruptcy Clause to waive states' immunity, as the bankruptcy court did, the Court held that ratification of the Clause itself involved a subordination of state sovereign immunity.","sumSrc":"Oyez","by":{"2":"50"}},{"t":"case","label":"Citizens to Preserve Overton Park, Inc. v. Volpe","cite":"401 U.S. 402","y":1971,"id":"1970/1066","sc":1,"sum":"Under § 4 (f) of the Department. of Transportation Act of 1966 and § 138 of the Federal-Aid Highway Act of 1968, the Secretary of Transportation may not authorize use of federal funds to finance construction of highways through public parks if a \"feasible and prudent\" alternative route exists. If no such route is available, he may approve construction only if there has been \"all possible planning to minimize harm\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46","3":"17"}},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"136 S. Ct. 2131","y":2016,"id":"2015/15-446","sc":1,"sum":"The Court held that the Patent Trial and Appeal Board may apply the broadest reasonable interpretation of patent claims during an inter partes review proceeding, and such a proceeding is not judicially reviewable.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Department of Homeland Sec. v. MacLean","cite":"135 S. Ct. 913","y":2015,"id":"2014/13-894","sc":1,"sum":"The Court ruled that the Whistleblower Protection Act bars an agency from taking enforcement action against employees who intentionally disclose sensitive security information.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"case","label":"GDF Realty Invs., Ltd. v. Norton","cite":"326 F.3d 622","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/326/622/","by":{"2":"44"}},{"t":"case","label":"Gibbs v. Babbitt","cite":"214 F.3d 483","y":2000,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/214/483/","by":{"2":"44"}},{"t":"case","label":"Gifford Pinchot Task Force v. United States Fish & Wildlife Serv.","cite":"378 F.3d 1059","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/378/1059/","by":{"2":"4"}},{"t":"case","label":"Gonzales v. Raich","cite":"545 U.S. 1","y":2005,"id":"2004/03-1454","sc":1,"sum":"The Court ruled that the commerce clause of the Controlled Substances Act gives Congress authority to prohibit the local cultivation and use of marijuana, despite state law to the contrary.","sumSrc":"Oyez","by":{"2":"44","3":"13"}},{"t":"case","label":"ICC v. Brotherhood of Locomotive Eng’rs","cite":"482 U.S. 270","y":1987,"id":"1986/85-792","sc":1,"op":1,"sum":"In October 1982, petitioner Interstate Commerce Commission (ICC or Commission) issued an order, which, inter alia, granted petitioner Missouri-Kansas-Texas Railroad Co. and another railroad the right to conduct operations using the tracks of a third, newly consolidated carrier. In April 1983, respondent Brotherhood of Locomotive Engineers (BLE) filed a \"Petition for Clarification\" asking the ICC to declare that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"52"}},{"t":"case","label":"INS v. Yang","cite":"519 U.S. 26","y":1996,"id":"1996/95-938","sc":1,"sum":"Authored by Justice Antonin Scalia, the Court ruled that in deciding whether to grant a waiver under the Immigration and Nationality Act, the Attorney General or her delegate, the Immigration and Naturalization Service, may take into account acts of fraud committed by the alien in connection to his entry into the United States.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"2":"42, 43, 44"}},{"t":"case","label":"Lincoln v. Vigil","cite":"508 U.S. 182","y":1993,"id":"1992/91-1833","sc":1,"op":3,"sum":"The Indian Health Service receives yearly lump-sum appropriations from Congress, and expends the funds under authority of the Snyder Act and the Indian Health Care Improvement Act to provide health care for American Indian and Alaska Native people. Out of these appropriations the Service funded, from 1978 to 1985, the Indian Children's Program (Program), which provided clinical services to handicapped Indian …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"49","3":"17"}},{"t":"case","label":"Marsh v. Oregon Nat. Res. Council","cite":"490 U.S. 360","y":1989,"id":"1988/87-1704","sc":1,"sum":"The Elk Creek Dam is part of a three-dam project designed to control the water supply in Oregon's Rogue River Basin. The Army Corps of Engineers (Corps) completed an Environmental Impact Statement (EIS) for the Elk Creek project in 1971, and, in 1980, released its final Environmental Impact Statement, Supplement No. 1 (FEISS). Since the Rogue River is a premier fishing ground, the FEISS paid special heed to water …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Merit Mgmt. Grp., LP v. FTI Consulting, Inc.","cite":"138 S. Ct. 883","y":2018,"id":"2017/16-784","sc":1,"sum":"The Court held that the safe harbor provision of 11 U.S.C. § 546(e), which prohibits a trustee from avoiding a transfer made by or to a financial institution, does not include transfers where the benefit and detriment of the transfer impact companies that are not financial institutions.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Murr v. Wisconsin","cite":"137 S. Ct. 1933","y":2017,"id":"2016/15-214","sc":1,"sum":"The Court determined that, in a regulatory takings case, two legally distinct but commonly owned contiguous parcels should be combined for takings analysis purposes.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Oregon Nat. Res. Council v. Allen","cite":"476 F.3d 1031","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/476/1031/","by":{"2":"29"}},{"t":"case","label":"People for Ethical Treatment of Prop. Owners v. United States Fish & Wildlife Serv.","cite":"852 F.3d 990","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/852/990/","by":{"2":"42"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"2":"28, 32"}},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"138 S. Ct. 816","y":2018,"id":"2017/16-534","sc":1,"sum":"The Court held that 28 U.S.C. § 1610(g) does not provide a freestanding attachment immunity exception that allows terror victim judgment creditors to attach and execute upon assets of foreign state; rather, the immunity of property must be rescinded under a separate provision under that section.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"San Luis & Delta-Mendota Water Auth. v. Salazar","cite":"638 F.3d 1163","y":2011,"url":"https://www.courtlistener.com/c/F.3d/638/1163/","by":{"2":"44"}},{"t":"case","label":"Sierra Club v. U.S. Fish & Wildlife Serv.","cite":"245 F.3d 434","y":2001,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/245/434/","sum":"Noting these “informational benefits”.","sumSrc":"brief:2","by":{"2":"4, 42"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"op":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Wild Fish Conservancy v. Salazar","cite":"628 F.3d 513","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/628/513/","by":{"2":"30"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"2":"32"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"by":{"2":"13"}},{"t":"usc","label":"33 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/33/1344","subs":["(a)"],"stext":{"head":"§1344. Permits for dredged or fill material","paras":[[0,"(a) Discharge into navigable waters at specified disposal sites"],[0,"The Secretary may issue permits, after notice and opportunity for public hearings for the discharge of dredged or fill material into the navigable waters at specified disposal sites. Not later than the fifteenth day after the date an applicant submits all the information required to complete an application for a permit under this subsection, the Secretary shall publish the notice required by this subsection."],[0,"(b) Specification for disposal sites"],[0,"Subject to subsection (c) of this section, each such disposal site shall be specified for each such permit by the Secretary (1) through the application of guidelines developed by the Administrator, in conjunction with the Secretary, which guidelines shall be based upon criteria comparable to the criteria applicable to the territorial seas, the contiguous zone, and the ocean under section 1343(c) of this title, and (2) in any case where such guidelines under clause (1) alone would prohibit the specification of a site, through the application additionally of the economic impact of the site on navigation and anchorage."],[0,"(c) Denial or restriction of use of defined areas as disposal sites"],[0,"The Administrator is authorized to prohibit the specification (including the withdrawal of specification) of any defined area as a disposal site, and he is authorized to deny or restrict the use of any defined area for specification (including the withdrawal of specification) as a disposal site, whenever he determines, after notice and opportunity for public hearings, that the discharge of such materials into such area will have an unacceptable adverse effect on municipal water supplies, shellfish beds and fishery areas (including spawning and breeding areas), wildlife, or recreational areas. Before making such determination, the Administrator shall consult with the Secretary. The Administrator shall set forth in writing and make public his findings and his reasons for making any determination under this subsection."],[0,"(d) \"Secretary\" defined"],[0,"The term \"Secretary\" as used in this section means the Secretary of the Army, acting through the Chief of Engineers."],[0,"(e) General permits on State, regional, or nationwide basis"],[0,"(1) In carrying out his functions relating to the discharge of dredged or fill material under this section, the Secretary may, after notice and opportunity for public hearing, issue general permits on a State, regional, or nationwide basis for any category of activities involving discharges of dredged or fill material if the Secretary determines that the activities in such category are similar in nature, will cause only minimal adverse environmental effects when performed separately, and will have only minimal cumulative adverse effect on the environment. Any general permit issued under this subsection shall (A) be based on the guidelines described in subsection (b)(1) of this section, and (B) set forth the requirements and standards which shall apply to any activity authorized by such general permit."],[0,"(2) No general permit issued under this subsection shall be for a period of more than five years after the date of its issuance and such general permit may be revoked or modified by the Secretary if, after opportunity for public hearing, the Secretary determines that the activities authorized by such general permit have an adverse impact on the environment or such activities are more appropriately authorized by individual permits."],[0,"(f) Non-prohibited discharge of dredged or fill material"],[0,"(1) Except as provided in paragraph (2) of this subsection, the discharge of dredged or fill material—"],[1,"(A) from normal farming, silviculture, and ranching activities such as plowing, seeding, cultivating, minor drainage, harvesting for the production of food, fiber, and forest products, or upland soil and water conservation practices;"],[1,"(B) for the purpose of maintenance, including emergency reconstruction of recently damaged parts, of currently serviceable structures such as dikes, dams, levees, groins, riprap, breakwaters, causeways, and bridge abutments or approaches, and transportation structures;"],[1,"(C) for the purpose of construction or maintenance of farm or stock ponds or irrigation ditches, or the maintenance of drainage ditches;"],[1,"(D) for the purpose of construction of temporary sedimentation basins on a construction site which does not include placement of fill material into the navigable waters;"],[1,"(E) for the purpose of construction or maintenance of farm roads or forest roads, or temporary roads for moving mining equipment, where such roads are constructed and maintained, in accordance with best management practices, to assure that flow and circulation patterns and chemical and biological characteristics of the navigable waters are not impaired, that the reach of the navigable waters is not reduced, and that any adverse effect on the aquatic environment will be otherwise minimized;"],[1,"(F) resulting from any activity with respect to which a State has an approved program under section 1288(b)(4) of this title which meets the requirements of subparagraphs (B) and (C) of such section,"],[0,"is not prohibited by or otherwise subject to regulation under this section or section 1311(a) or 1342 of this title (except for effluent standards or prohibitions under section 1317 of this title)."],[0,"(2) Any discharge of dredged or fill material into the navigable waters incidental to any activity having as its purpose bringing an area of the navigable waters into a use to which it was not previously subject, where the flow or circulation of navigable waters may be impaired or the reach of such waters be reduced, shall be required to have a permit under this section."],[0,"(g) State administration"],[0,"(1) The Governor of any State desiring to administer its own individual and general permit program for the discharge of dredged or fill material into the navigable waters (other than those waters which are presently used, or are susceptible to use in their natural condition or by reasonable improvement as a means to transport interstate or foreign commerce shoreward to their ordinary high water mark, including all waters which are subject to the ebb and flow of the tide shoreward to their mean high water mark, or mean higher high water mark on the west coast, including wetlands adjacent thereto) within its jurisdiction may submit to the Administrator a full and complete description of the program it proposes to establish and administer under State law or under an interstate compact. In addition, such State shall submit a statement from the attorney general (or the attorney for those State agencies which have independent legal counsel), or from the chief legal officer in the case of an interstate agency, that the laws of such State, or the interstate compact, as the case may be, provide adequate authority to carry out the described program."],[0,"(2) Not later than the tenth day after the date of the receipt of the program and statement submitted by any State under paragraph (1) of this subsection, the Administrator shall provide copies of such program and statement to the Secretary and the Secretary of the Interior, acting through the Director of the United States Fish and Wildlife Service."],[0,"(3) Not later than the ninetieth day after the date of the receipt by the Administrator of the program and statement submitted by any State, under paragraph (1) of this subsection, the Secretary and the Secretary of the Interior, acting through the Director of the United States Fish and Wildlife Service, shall submit any comments with respect to such program and statement to the Administrator in writing."],[0,"(h) Determination of State's authority to issue permits under State program; approval; notification; transfers to State program"],[0,"(1) Not later than the one-hundred-twentieth day after the date of the receipt by the Administrator of a program and statement submitted by any State under paragraph (1) of this subsection, the Administrator shall determine, taking into account any comments submitted by the Secretary and the Secretary of the Interior, acting through the Director of the United States Fish and Wildlife Service, pursuant to subsection (g) of this section, whether such State has the following authority with respect to the issuance of permits pursuant to such program:"],[1,"(A) To issue permits which—"],[2,"(i) apply, and assure compliance with, any applicable requirements of this section, including, but not limited to, the guidelines established under subsection (b)(1) of this section, and sections 1317 and 1343 of this title;"],[2,"(ii) are for fixed terms not exceeding five years; and"],[2,"(iii) can be terminated or modified for cause including, but not limited to, the following:"],[3,"(I) violation of any condition of the permit;"],[3,"(II) obtaining a permit by misrepresentation, or failure to disclose fully all relevant facts;"],[3,"(III) change in any condition that requires either a temporary or permanent reduction or elimination of the permitted discharge."],[1,"(B) To issue permits which apply, and assure compliance with, all applicable requirements of section 1318 of this title, or to inspect, monitor, enter, and require reports to at least the same extent as required in section 1318 of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1344?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1344. Permits for dredged or fill material","tname":"Navigation and Navigable Waters","by":{"2":"13"}},{"t":"usc","label":"16 U.S.C. § 1533","url":"https://www.law.cornell.edu/uscode/text/16/1533","subs":["(a)(1)(A)","(a)(1)","(a)(3)(A)(i)","(b)(2)","(b)(3)","(b)(3)(D)(i)","(c)(1)"],"stext":{"head":"§1533. Determination of endangered species and threatened species","paras":[[0,"(a) Generally"],[0,"(1) The Secretary shall by regulation promulgated in accordance with subsection (b) determine whether any species is an endangered species or a threatened species because of any of the following factors:"],[1,"(A) the present or threatened destruction, modification, or curtailment of its habitat or range;"],[1,"(B) overutilization for commercial, recreational, scientific, or educational purposes;"],[1,"(C) disease or predation;"],[1,"(D) the inadequacy of existing regulatory mechanisms; or"],[1,"(E) other natural or manmade factors affecting its continued existence."],[0,"(2) With respect to any species over which program responsibilities have been vested in the Secretary of Commerce pursuant to Reorganization Plan Numbered 4 of 1970—"],[1,"(A) in any case in which the Secretary of Commerce determines that such species should—"],[2,"(i) be listed as an endangered species or a threatened species, or"],[2,"(ii) be changed in status from a threatened species to an endangered species,"],[1,"he shall so inform the Secretary of the Interior; who shall list such species in accordance with this section;"],[1,"(B) in any case in which the Secretary of Commerce determines that such species should—"],[2,"(i) be removed from any list published pursuant to subsection (c) of this section, or"],[2,"(ii) be changed in status from an endangered species to a threatened species,"],[1,"he shall recommend such action to the Secretary of the Interior, and the Secretary of the Interior, if he concurs in the recommendation, shall implement such action; and"],[1,"(C) the Secretary of the Interior may not list or remove from any list any such species, and may not change the status of any such species which are listed, without a prior favorable determination made pursuant to this section by the Secretary of Commerce."],[0,"(3)(A) The Secretary, by regulation promulgated in accordance with subsection (b) and to the maximum extent prudent and determinable—"],[1,"(i) shall, concurrently with making a determination under paragraph (1) that a species is an endangered species or a threatened species, designate any habitat of such species which is then considered to be critical habitat; and"],[1,"(ii) may, from time-to-time thereafter as appropriate, revise such designation."],[0,"(B)(i) The Secretary shall not designate as critical habitat any lands or other geographical areas owned or controlled by the Department of Defense, or designated for its use, that are subject to an integrated natural resources management plan prepared under section 670a of this title, if the Secretary determines in writing that such plan provides a benefit to the species for which critical habitat is proposed for designation."],[0,"(ii) Nothing in this paragraph affects the requirement to consult under section 1536(a)(2) of this title with respect to an agency action (as that term is defined in that section)."],[0,"(iii) Nothing in this paragraph affects the obligation of the Department of Defense to comply with section 1538 of this title, including the prohibition preventing extinction and taking of endangered species and threatened species."],[0,"(b) Basis for determinations"],[0,"(1)(A) The Secretary shall make determinations required by subsection (a)(1) solely on the basis of the best scientific and commercial data available to him after conducting a review of the status of the species and after taking into account those efforts, if any, being made by any State or foreign nation, or any political subdivision of a State or foreign nation, to protect such species, whether by predator control, protection of habitat and food supply, or other conservation practices, within any area under its jurisdiction; or on the high seas."],[0,"(B) In carrying out this section, the Secretary shall give consideration to species which have been—"],[1,"(i) designated as requiring protection from unrestricted commerce by any foreign nation, or pursuant to any international agreement; or"],[1,"(ii) identified as in danger of extinction, or likely to become so within the foreseeable future, by any State agency or by any agency of a foreign nation that is responsible for the conservation of fish or wildlife or plants."],[0,"(2) The Secretary shall designate critical habitat, and make revisions thereto, under subsection (a)(3) on the basis of the best scientific data available and after taking into consideration the economic impact, the impact on national security, and any other relevant impact, of specifying any particular area as critical habitat. The Secretary may exclude any area from critical habitat if he determines that the benefits of such exclusion outweigh the benefits of specifying such area as part of the critical habitat, unless he determines, based on the best scientific and commercial data available, that the failure to designate such area as critical habitat will result in the extinction of the species concerned."],[0,"(3)(A) To the maximum extent practicable, within 90 days after receiving the petition of an interested person under section 553(e) of title 5, to add a species to, or to remove a species from, either of the lists published under subsection (c), the Secretary shall make a finding as to whether the petition presents substantial scientific or commercial information indicating that the petitioned action may be warranted. If such a petition is found to present such information, the Secretary shall promptly commence a review of the status of the species concerned. The Secretary shall promptly publish each finding made under this subparagraph in the Federal Register."],[0,"(B) Within 12 months after receiving a petition that is found under subparagraph (A) to present substantial information indicating that the petitioned action may be warranted, the Secretary shall make one of the following findings:"],[1,"(i) The petitioned action is not warranted, in which case the Secretary shall promptly publish such finding in the Federal Register."],[1,"(ii) The petitioned action is warranted, in which case the Secretary shall promptly publish in the Federal Register a general notice and the complete text of a proposed regulation to implement such action in accordance with paragraph (5)."],[1,"(iii) The petitioned action is warranted, but that—"],[2,"(I) the immediate proposal and timely promulgation of a final regulation implementing the petitioned action in accordance with paragraphs (5) and (6) is precluded by pending proposals to determine whether any species is an endangered species or a threatened species, and"],[2,"(II) expeditious progress is being made to add qualified species to either of the lists published under subsection (c) and to remove from such lists species for which the protections of this chapter are no longer necessary,"],[1,"in which case the Secretary shall promptly publish such finding in the Federal Register, together with a description and evaluation of the reasons and data on which the finding is based."],[0,"(C)(i) A petition with respect to which a finding is made under subparagraph (B)(iii) shall be treated as a petition that is resubmitted to the Secretary under subparagraph (A) on the date of such finding and that presents substantial scientific or commercial information that the petitioned action may be warranted."],[0,"(ii) Any negative finding described in subparagraph (A) and any finding described in subparagraph (B)(i) or (iii) shall be subject to judicial review."],[0,"(iii) The Secretary shall implement a system to monitor effectively the status of all species with respect to which a finding is made under subparagraph (B)(iii) and shall make prompt use of the authority under paragraph 7 1 to prevent a significant risk to the well being of any such species."],[0,"(D)(i) To the maximum extent practicable, within 90 days after receiving the petition of an interested person under section 553(e) of title 5, to revise a critical habitat designation, the Secretary shall make a finding as to whether the petition presents substantial scientific information indicating that the revision may be warranted. The Secretary shall promptly publish such finding in the Federal Register."],[0,"(ii) Within 12 months after receiving a petition that is found under clause (i) to present substantial information indicating that the requested revision may be warranted, the Secretary shall determine how he intends to proceed with the requested revision, and shall promptly publish notice of such intention in the Federal Register."],[0,"(4) Except as provided in paragraphs (5) and (6) of this subsection, the provisions of section 553 of title 5 (relating to rulemaking procedures), shall apply to any regulation promulgated to carry out the purposes of this chapter."],[0,"(5) With respect to any regulation proposed by the Secretary to implement a determination, designation, or revision referred to in subsection (a)(1) or (3), the Secretary shall—"],[1,"(A) not less than 90 days before the effective date of the regulation—"],[2,"(i) publish a general notice and the complete text of the proposed regulation in the Federal Register, and"],[2,"(ii) give actual notice of the proposed regulation (including the complete text of the regulation) to the State agency in each State in which the species is believed to occur, and to each county, or equivalent jurisdiction in which the species is believed to occur, and invite the comment of such agency, and each such jurisdiction, thereon;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1533?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1533. Determination of endangered species and threatened species","tname":"Conservation","by":{"2":"2, 2, 2, 2, 2, 2, 2, 2"}},{"t":"usc","label":"16 U.S.C. § 1534","url":"https://www.law.cornell.edu/uscode/text/16/1534","by":{"2":"5"}},{"t":"usc","label":"16 U.S.C. § 1535","url":"https://www.law.cornell.edu/uscode/text/16/1535","by":{"2":"5"}},{"t":"usc","label":"16 U.S.C. § 1536","url":"https://www.law.cornell.edu/uscode/text/16/1536","subs":["(a)","(a)(1)","(a)(2)","(b)(3)(A)"],"stext":{"head":"§1536. Interagency cooperation","paras":[[0,"(a) Federal agency actions and consultations"],[0,"(1) The Secretary shall review other programs administered by him and utilize such programs in furtherance of the purposes of this chapter. All other Federal agencies shall, in consultation with and with the assistance of the Secretary, utilize their authorities in furtherance of the purposes of this chapter by carrying out programs for the conservation of endangered species and threatened species listed pursuant to section 1533 of this title."],[0,"(2) Each Federal agency shall, in consultation with and with the assistance of the Secretary, insure that any action authorized, funded, or carried out by such agency (hereinafter in this section referred to as an \"agency action\") is not likely to jeopardize the continued existence of any endangered species or threatened species or result in the destruction or adverse modification of habitat of such species which is determined by the Secretary, after consultation as appropriate with affected States, to be critical, unless such agency has been granted an exemption for such action by the Committee pursuant to subsection (h) of this section. In fulfilling the requirements of this paragraph each agency shall use the best scientific and commercial data available."],[0,"(3) Subject to such guidelines as the Secretary may establish, a Federal agency shall consult with the Secretary on any prospective agency action at the request of, and in cooperation with, the prospective permit or license applicant if the applicant has reason to believe that an endangered species or a threatened species may be present in the area affected by his project and that implementation of such action will likely affect such species."],[0,"(4) Each Federal agency shall confer with the Secretary on any agency action which is likely to jeopardize the continued existence of any species proposed to be listed under section 1533 of this title or result in the destruction or adverse modification of critical habitat proposed to be designated for such species. This paragraph does not require a limitation on the commitment of resources as described in subsection (d)."],[0,"(b) Opinion of Secretary"],[0,"(1)(A) Consultation under subsection (a)(2) with respect to any agency action shall be concluded within the 90-day period beginning on the date on which initiated or, subject to subparagraph (B), within such other period of time as is mutually agreeable to the Secretary and the Federal agency."],[0,"(B) In the case of an agency action involving a permit or license applicant, the Secretary and the Federal agency may not mutually agree to conclude consultation within a period exceeding 90 days unless the Secretary, before the close of the 90th day referred to in subparagraph (A)—"],[1,"(i) if the consultation period proposed to be agreed to will end before the 150th day after the date on which consultation was initiated, submits to the applicant a written statement setting forth—"],[2,"(I) the reasons why a longer period is required,"],[2,"(II) the information that is required to complete the consultation, and"],[2,"(III) the estimated date on which consultation will be completed; or"],[1,"(ii) if the consultation period proposed to be agreed to will end 150 or more days after the date on which consultation was initiated, obtains the consent of the applicant to such period."],[0,"The Secretary and the Federal agency may mutually agree to extend a consultation period established under the preceding sentence if the Secretary, before the close of such period, obtains the consent of the applicant to the extension."],[0,"(2) Consultation under subsection (a)(3) shall be concluded within such period as is agreeable to the Secretary, the Federal agency, and the applicant concerned."],[0,"(3)(A) Promptly after conclusion of consultation under paragraph (2) or (3) of subsection (a), the Secretary shall provide to the Federal agency and the applicant, if any, a written statement setting forth the Secretary's opinion, and a summary of the information on which the opinion is based, detailing how the agency action affects the species or its critical habitat. If jeopardy or adverse modification is found, the Secretary shall suggest those reasonable and prudent alternatives which he believes would not violate subsection (a)(2) and can be taken by the Federal agency or applicant in implementing the agency action."],[0,"(B) Consultation under subsection (a)(3), and an opinion issued by the Secretary incident to such consultation, regarding an agency action shall be treated respectively as a consultation under subsection (a)(2), and as an opinion issued after consultation under such subsection, regarding that action if the Secretary reviews the action before it is commenced by the Federal agency and finds, and notifies such agency, that no significant changes have been made with respect to the action and that no significant change has occurred regarding the information used during the initial consultation."],[0,"(4) If after consultation under subsection (a)(2), the Secretary concludes that—"],[1,"(A) the agency action will not violate such subsection, or offers reasonable and prudent alternatives which the Secretary believes would not violate such subsection;"],[1,"(B) the taking of an endangered species or a threatened species incidental to the agency action will not violate such subsection; and"],[1,"(C) if an endangered species or threatened species of a marine mammal is involved, the taking is authorized pursuant to section 1371(a)(5) of this title;"],[0,"the Secretary shall provide the Federal agency and the applicant concerned, if any, with a written statement that—"],[1,"(i) specifies the impact of such incidental taking on the species,"],[1,"(ii) specifies those reasonable and prudent measures that the Secretary considers necessary or appropriate to minimize such impact,"],[1,"(iii) in the case of marine mammals, specifies those measures that are necessary to comply with section 1371(a)(5) of this title with regard to such taking, and"],[1,"(iv) sets forth the terms and conditions (including, but not limited to, reporting requirements) that must be complied with by the Federal agency or applicant (if any), or both, to implement the measures specified under clauses (ii) and (iii)."],[0,"(c) Biological assessment"],[0,"(1) To facilitate compliance with the requirements of subsection (a)(2), each Federal agency shall, with respect to any agency action of such agency for which no contract for construction has been entered into and for which no construction has begun on November 10, 1978, request of the Secretary information whether any species which is listed or proposed to be listed may be present in the area of such proposed action. If the Secretary advises, based on the best scientific and commercial data available, that such species may be present, such agency shall conduct a biological assessment for the purpose of identifying any endangered species or threatened species which is likely to be affected by such action. Such assessment shall be completed within 180 days after the date on which initiated (or within such other period as is mutually agreed to by the Secretary and such agency, except that if a permit or license applicant is involved, the 180-day period may not be extended unless such agency provides the applicant, before the close of such period, with a written statement setting forth the estimated length of the proposed extension and the reasons therefor) and, before any contract for construction is entered into and before construction is begun with respect to such action. Such assessment may be undertaken as part of a Federal agency's compliance with the requirements of section 102 of the National Environmental Policy Act of 1969 (42 U.S.C. 4332)."],[0,"(2) Any person who may wish to apply for an exemption under subsection (g) of this section for that action may conduct a biological assessment to identify any endangered species or threatened species which is likely to be affected by such action. Any such biological assessment must, however, be conducted in cooperation with the Secretary and under the supervision of the appropriate Federal agency."],[0,"(d) Limitation on commitment of resources"],[0,"After initiation of consultation required under subsection (a)(2), the Federal agency and the permit or license applicant shall not make any irreversible or irretrievable commitment of resources with respect to the agency action which has the effect of foreclosing the formulation or implementation of any reasonable and prudent alternative measures which would not violate subsection (a)(2) of this section."],[0,"(e) Endangered Species Committee"],[0,"(1) There is established a committee to be known as the Endangered Species Committee (hereinafter in this section referred to as the \"Committee\")."],[0,"(2) The Committee shall review any application submitted to it pursuant to this section and determine in accordance with subsection (h) of this section whether or not to grant an exemption from the requirements of subsection (a)(2) of this section for the action set forth in such application."],[0,"(3) The Committee shall be composed of seven members as follows:"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1536?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1536. Interagency cooperation","tname":"Conservation","by":{"2":"5, 5, 5, 5, 5"}},{"t":"usc","label":"16 U.S.C. § 1538","url":"https://www.law.cornell.edu/uscode/text/16/1538","subs":["(a)(1)(A)","(a)(1)(B)","(a)(1)(D)"],"by":{"2":"5, 5, 5, 5"}},{"t":"usc","label":"16 U.S.C. § 1539","url":"https://www.law.cornell.edu/uscode/text/16/1539","by":{"2":"5, 5, 5"}},{"t":"usc","label":"16 U.S.C. § 1540","url":"https://www.law.cornell.edu/uscode/text/16/1540","subs":["(a)","(g)(1)(A)","(g)(1)(C)"],"by":{"2":"5, 45, 50"}},{"t":"usc","label":"16 U.S.C. § 460ss-1","url":"https://www.law.cornell.edu/uscode/text/16/460ss-1","subs":["(b)(2)(B)(i)"],"by":{"2":"30"}},{"t":"usc","label":"16 U.S.C. § 1440","url":"https://www.law.cornell.edu/uscode/text/16/1440","subs":["(b)(1)(B)"],"by":{"2":"29"}},{"t":"usc","label":"16 U.S.C. § 3501","url":"https://www.law.cornell.edu/uscode/text/16/3501","subs":["(a)(1)(B)"],"by":{"2":"29"}},{"t":"usc","label":"16 U.S.C. § 6602","url":"https://www.law.cornell.edu/uscode/text/16/6602","subs":["(2)"],"by":{"2":"29"}},{"t":"usc","label":"16 U.S.C. § 6603","url":"https://www.law.cornell.edu/uscode/text/16/6603","subs":["(b)(1)(A)"],"by":{"2":"29"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(b)"],"by":{"2":"49"}},{"t":"reg","label":"56 Fed. Reg. 40,002","url":"https://www.govinfo.gov/link/fr/56/40002","by":{"2":"27"}},{"t":"reg","label":"67 Fed. Reg. 40,790","url":"https://www.govinfo.gov/link/fr/67/40790","by":{"2":"27"}},{"t":"reg","label":"73 Fed. Reg. 61,936","url":"https://www.govinfo.gov/link/fr/73/61936","by":{"2":"26, 27"}},{"t":"reg","label":"78 Fed. Reg. 8746","url":"https://www.govinfo.gov/link/fr/78/8746","by":{"2":"27"}},{"t":"reg","label":"78 Fed. Reg. 10,450","url":"https://www.govinfo.gov/link/fr/78/10450","by":{"2":"28"}},{"t":"reg","label":"79 Fed. Reg. 69,312","url":"https://www.govinfo.gov/link/fr/79/69312","by":{"2":"26"}},{"t":"reg","label":"81 Fed. Reg. 7226","url":"https://www.govinfo.gov/link/fr/81/7226","by":{"2":"3, 42, 48"}},{"t":"reg","label":"81 Fed. Reg. 59,045","url":"https://www.govinfo.gov/link/fr/81/59045","by":{"2":"28"}},{"t":"reg","label":"82 Fed. Reg. 39,160","url":"https://www.govinfo.gov/link/fr/82/39160","by":{"2":"26"}},{"t":"case","label":"Alaska Dep’t of Envtl. Conservation v. EPA","cite":"540 U.S. 461","y":2004,"id":"2003/02-658","sc":1,"ar":3,"sum":"The Court held that the Clean Air Act authorized the EPA to bar the construction of the polluting facility in Alaska. Though Alaska determined the facility's use of \"Low NOx\" met the act's requirement that facilities use \"best available control technology,\" the EPA was reasonable to reject this claim.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Ass’n of Data Processing Serv. Orgs., Inc. v. Camp","cite":"397 U.S. 150","y":1970,"id":"1969/85","sc":1,"sum":"Petitioners, which provide data processing services to businesses generally, challenge a ruling by the Comptroller of the Currency permitting national banks, such as respondent bank, as an incident to their banking services, to make data processing services available to other banks and bank customers. The District Court dismissed the complaint, holding that petitioners lacked standing to bring the suit, and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"19"}},{"t":"case","label":"Barlow v. Collins","cite":"397 U.S. 159","y":1970,"id":"1969/249","sc":1,"sum":"Petitioners, who are tenant farmers eligible for payments under the upland cotton program, enacted as part of the Food and Agriculture Act of 1965, challenge the validity of an amended. regulation issued by the Secretary of Agriculture in.1966. The program incorporates § 8 (g) of the Soil Conservation and Domestic Allotment Act, thereby permitting participating farmers to assign payments only \"as security for cash …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"16"}},{"t":"case","label":"Bryant v. Yellen","cite":"447 U.S. 352","y":1980,"id":"1979/79-421","sc":1,"sum":"The principal question in this action is whether the general rule under federal reclamation laws limiting irrigation water deliveries from reclamation projects to 160 acres under single ownership applies to certain private lands in Imperial Valley, Cal., being irrigated with Colorado River water through the irrigation system constructed pursuant to the Boulder Canyon Project Act (Project Act). When the Project Act …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"19"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"sum":"A case in which the Court declared that pieces of legislation passed by both houses of Congress must be either passed or vetoed as a whole, not in separate parts.","sumSrc":"Oyez","by":{"3":"19, 20"}},{"t":"case","label":"Czyzewski v. Jevic Holding Corp.","cite":"137 S. Ct. 973","y":2017,"id":"2016/15-649","sc":1,"sum":"The Court determined that bankruptcy court cannot authorize a distribution of settlement proceeds in a manner that does not comply with the Bankruptcy Code’s priority distribution scheme.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Fla. Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"12"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"F.D.I.C. v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"4"}},{"t":"case","label":"Inova Alexandria Hosp. v. Shalala","cite":"244 F.3d 342","y":2001,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/244/342/","by":{"3":"16"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"ar":1,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Massachusetts v. EPA","cite":"549 U.S. 497","y":2007,"id":"2006/05-1120","sc":1,"sum":"The Court ruled that states could sue the EPA for potential damage to their territory caused by global warming, and that the Clean Air Act imposes a duty upon the EPA to regulate the emissions of carbon dioxide and other gases that contribute to global warming.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"Miller v. Johnson","cite":"515 U.S. 900","y":1995,"id":"1994/94-631","sc":1,"sum":"In some instances, a reapportionment plan may be so highly irregular and bizarre in shape that it rationally cannot be understood as anything other than an effort to segregate voters based on race. Applying the rule laid down in Shaw v. Reno requires strict scrutiny whenever race is the \"overriding, predominant force\" in the redistricting process.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"Mulloy v. United States","cite":"398 U.S. 410","y":1970,"id":"1969/655","sc":1,"sum":"Where a registrant makes nonfrivolous allegations of facts not previously considered by his board, that, if true, would be sufficient under the regulations to warrant granting a reclassification, the board must reopen the classification, unless the truth of the new allegations is conclusively refuted by other reliable information in registrant's file, thus affording the registrant an administrative appeal from an …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"16"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"3":"10"}},{"t":"case","label":"Nat’l Park Hospitality Ass’n v. Dep’t of Interior","cite":"538 U.S. 803","y":2003,"id":"2002/02-196","sc":1,"sum":"The Court held that the controversy was not yet ripe for judicial resolution.","sumSrc":"Oyez","by":{"3":"20, 21"}},{"t":"case","label":"Otay Mesa Prop., L.P. v. U.S. Dep’t of Interior","cite":"646 F.3d 914","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/646/914/","by":{"3":"21"}},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"136 S. Ct. 1540","y":2016,"id":"2015/13-1339","sc":1,"sum":"The Court held that lower courts need to consider the elements of Article III standing analysis separately in determining whether standing is sufficient for a federal court to hear the case.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"867 F.3d 1108","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/867/1108/","by":{"3":"20"}},{"t":"case","label":"Stop the Beach Renourishment, Inc. v. Fla. Dep’t of Envtl. Prot.","cite":"560 U.S. 702","y":2010,"id":"2009/08-1151","sc":1,"sum":"The Court held that a ruling on littoral (\"on or near the shore\") takings by the Florida Supreme Court did not cause a judicial takings violation of the Fifth or Fourteenth Amendments.","sumSrc":"Oyez","by":{"3":"21"}},{"t":"case","label":"U.S. Army Corps of Engineers v. Hawkes Co.","cite":"136 S. Ct. 1807","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1807/","sc":1,"by":{"3":"21"}},{"t":"case","label":"Vill. of Euclid v. Ambler Realty Co.","cite":"272 U.S. 365","y":1926,"id":"1900-1940/272us365","sc":1,"op":1,"sum":"Holding that a zoning ordinance that “greatly . . . reduce[d] the value of appellee’s lands and destroy[ed] their marketability for industrial, commercial and residential uses” constituted a “present invasion of appellee’s property rights”.","sumSrc":"opinion","by":{"3":"19"}},{"t":"case","label":"Wis. Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"3":"14"}},{"t":"reg","label":"50 C.F.R. § 402.02","url":"https://www.ecfr.gov/current/title-50/section-402.02","by":{"3":"21"}},{"t":"reg","label":"83 Fed. Reg. 35193","url":"https://www.govinfo.gov/link/fr/83/35193","by":{"3":"9"}}]};